<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue'
import{useRoute,useRouter}from'vue-router'
import{ElMessage,ElMessageBox}from'element-plus'
import api from'../../services/api'
import{confirmRecord,createRecord,completeVisit,updateRecord}from'../../services/records'
import{startAppointment}from'../../services/appointments'
import type{Appointment,MedicalRecord,PatientSummary,Prescription,ExaminationOrder,InpatientAdmission}from'../../types/medical'

interface Workspace{appointment:Appointment;patient:PatientSummary&Record<string,any>;current_record:MedicalRecord|null;history:MedicalRecord[];prescriptions:Prescription[];examinations:ExaminationOrder[];admissions:InpatientAdmission[]}
const route=useRoute(),router=useRouter(),loading=ref(false),saving=ref(false),data=ref<Workspace|null>(null)
const form=reactive({chief_complaint:'',present_illness:'',past_history:'',examination:'',diagnosis:'',treatment:''})
const appointmentId=computed(()=>Number(route.params.appointmentId))
function errorText(e:any,fallback:string){const body=e.response?.data;if(body?.errors){const first=Object.values(body.errors)[0] as any;return Array.isArray(first)?first.join('；'):String(first)}return body?.detail||fallback}
function fill(record:MedicalRecord|null){Object.assign(form,{chief_complaint:record?.chief_complaint||'',present_illness:record?.present_illness||'',past_history:record?.past_history||'',examination:record?.examination||'',diagnosis:record?.diagnosis||'',treatment:record?.treatment||''})}
async function load(){loading.value=true;try{data.value=(await api.get(`appointments/${appointmentId.value}/workspace/`)).data;fill(data.value?.current_record||null)}catch(e:any){ElMessage.error(errorText(e,'诊疗工作区加载失败'))}finally{loading.value=false}}
async function begin(){try{await startAppointment(appointmentId.value);ElMessage.success('已开始接诊');await load()}catch(e:any){ElMessage.error(errorText(e,'无法开始接诊'))}}
async function save(){if(!form.chief_complaint.trim()||!form.diagnosis.trim()){ElMessage.warning('请填写主诉和诊断');return}saving.value=true;try{const current=data.value?.current_record;if(current)await updateRecord(current.id,{...form});else await createRecord({appointment_id:appointmentId.value,...form});ElMessage.success('病历草稿已保存');await load()}catch(e:any){ElMessage.error(errorText(e,'病历保存失败'))}finally{saving.value=false}}
async function confirm(){const record=data.value?.current_record;if(!record)return;try{await ElMessageBox.confirm('确认后原始病历将锁定。','确认病历',{type:'warning'});await confirmRecord(record.id);ElMessage.success('病历已确认');await load()}catch(e:any){if(e!=='cancel'&&e!=='close')ElMessage.error(errorText(e,'确认失败'))}}
async function finish(){const record=data.value?.current_record;if(!record)return;try{await ElMessageBox.confirm('确定完成本次诊疗并归档吗？','完成诊疗');await completeVisit(record.id);ElMessage.success('诊疗已完成');await load()}catch(e:any){if(e!=='cancel'&&e!=='close')ElMessage.error(errorText(e,'无法完成诊疗'))}}
onMounted(load)
</script>
<template><section v-loading="loading"><div class="page-heading visit-heading"><div><el-button link @click="router.back()">← 返回接诊列表</el-button><h1>诊疗工作区</h1><p v-if="data">{{data.appointment.appointment_no}} · {{data.appointment.slot.date}} {{data.appointment.slot.start_time.slice(0,5)}} · {{data.appointment.department_name}}</p></div><div v-if="data" class="visit-actions"><el-tag size="large">{{data.appointment.status_display||data.appointment.status}}</el-tag><el-button v-if="data.appointment.status==='pending'" type="primary" @click="begin">开始接诊</el-button><el-button v-if="data.current_record?.status==='confirmed'&&data.appointment.status==='in_progress'" type="success" @click="finish">完成诊疗</el-button></div></div>
<template v-if="data"><div class="patient-band"><div><span>患者</span><strong>{{data.patient.full_name}}</strong><small>{{data.patient.patient_no}} · {{data.patient.gender_display||'未填写'}} · {{data.patient.phone||'无手机号'}}</small></div><div><span>过敏史</span><b>{{data.patient.allergies||'无已知过敏'}}</b></div><div><span>既往病史</span><b>{{data.patient.medical_history||'未记录'}}</b></div><div><span>本次就诊原因</span><b>{{data.appointment.reason}}</b></div></div>
<div class="visit-grid"><el-card class="clinical-editor"><template #header><div class="section-head"><div><h2>当前病历</h2><p>{{data.current_record?data.current_record.record_no:'本次就诊尚未建立病历'}}</p></div><el-tag v-if="data.current_record" :type="data.current_record.status==='confirmed'?'success':'warning'">{{data.current_record.status==='confirmed'?'已确认':'草稿'}}</el-tag></div></template><el-alert v-if="data.appointment.status==='pending'" title="请先开始接诊，再建立本次病历。" type="warning" :closable="false"/><el-form label-position="top" :disabled="data.appointment.status!=='in_progress'||data.current_record?.status==='confirmed'"><el-row :gutter="14"><el-col :md="12"><el-form-item label="主诉" required><el-input v-model="form.chief_complaint" type="textarea" :rows="3"/></el-form-item></el-col><el-col :md="12"><el-form-item label="现病史"><el-input v-model="form.present_illness" type="textarea" :rows="3"/></el-form-item></el-col><el-col :md="12"><el-form-item label="既往病史"><el-input v-model="form.past_history" type="textarea" :rows="3"/></el-form-item></el-col><el-col :md="12"><el-form-item label="体格/辅助检查"><el-input v-model="form.examination" type="textarea" :rows="3"/></el-form-item></el-col></el-row><el-form-item label="诊断" required><el-input v-model="form.diagnosis" type="textarea" :rows="2"/></el-form-item><el-form-item label="处理意见"><el-input v-model="form.treatment" type="textarea" :rows="3"/></el-form-item><div v-if="data.appointment.status==='in_progress'&&data.current_record?.status!=='confirmed'" class="editor-actions"><el-button type="primary" :loading="saving" @click="save">保存草稿</el-button><el-button v-if="data.current_record" type="success" plain @click="confirm">确认病历</el-button></div></el-form></el-card>
<aside class="visit-side"><el-card><template #header><div class="section-head"><div><h2>本次医疗事项</h2><p>处方、检查和住院申请</p></div></div></template><div class="care-counts"><router-link to="/doctor/prescriptions"><b>{{data.prescriptions.length}}</b><span>张处方</span></router-link><router-link to="/doctor/examinations"><b>{{data.examinations.length}}</b><span>项检查</span></router-link><router-link to="/doctor/inpatients"><b>{{data.admissions.length}}</b><span>条住院记录</span></router-link></div><el-alert v-if="!data.current_record||data.current_record.status!=='confirmed'" title="确认病历后可开具处方和检查。" type="info" :closable="false"/></el-card><el-card><template #header><div class="section-head"><div><h2>历史就诊</h2><p>最近 {{data.history.length}} 条已确认病历</p></div></div></template><el-timeline v-if="data.history.length"><el-timeline-item v-for="item in data.history" :key="item.id" :timestamp="item.visit_at"><b>{{item.diagnosis}}</b><p>{{item.treatment||'无处理意见'}}</p></el-timeline-item></el-timeline><el-empty v-else :image-size="60" description="暂无历史就诊"/></el-card></aside></div></template></section></template>
